import * as THREE from 'three/webgpu';
import { texture, uv, color, uniform, vec4 } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  const position = config.scenePosition || { x: 0, y: -0.3, z: 0 };
  const rotation = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scale = config.sceneScale || { x: 1, y: 1, z: 1 };

  group.position.set(position.x, position.y, position.z);
  group.rotation.set(rotation.x, rotation.y, rotation.z);
  group.scale.set(scale.x, scale.y, scale.z);

  const width = 1.28;
  const height = 0.8;

  const geometry = new THREE.PlaneGeometry(width, height);

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/orb-decor.png');

  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: texture(map).mul(color(config.visual.colors.surface || '#0b0b10'))
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  const tweens = [];

  if (config.cinematicPrimitives) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives && ctx.primitives[primitive.name]) {
        ctx.primitives[primitive.name](group, primitive.params);
      }
    }
  }

  group.userData.handlers = {};
  group.userData.tweens = tweens;

  group.userData.cleanup = () => {
    for (const t of tweens) {
      t.kill();
    }
    tweens.length = 0;
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
  };

  return group;
}
